
-- DROP DATABASE PRACTICE_DATA;

CREATE DATABASE PRACTICE_DATA;
USE PRACTICE_DATA;

-- Table: Managers
CREATE TABLE Managers (
    manager_id DOUBLE,
    manager_name VARCHAR(255),
    manager_level DOUBLE,
    manager_phone VARCHAR(255)
);

-- Table: Orders
CREATE TABLE Orders (
    ID DOUBLE,
    order_id DOUBLE,
    order_date DATETIME,
    order_priority VARCHAR(255),
    order_quantity DOUBLE,
    value DOUBLE,
    discount DOUBLE,
    shipping_mode VARCHAR(255),
    profit DOUBLE,
    unit_price DOUBLE,
    shipping_cost DOUBLE,
    customer_name VARCHAR(255),
    province VARCHAR(255),
    region VARCHAR(255),
    customer_segment VARCHAR(255),
    product_category VARCHAR(255),
    product_subcategory VARCHAR(255),
    product_name VARCHAR(255),
    product_container VARCHAR(255),
    product_base_margin DOUBLE,
    shipping_date DATETIME
);

-- Table: Profiles
CREATE TABLE Profiles (
    province VARCHAR(255),
    region VARCHAR(255),
    manager VARCHAR(255)
);

-- Table: Returns
CREATE TABLE Returns (
    order_id DOUBLE,
    status VARCHAR(255),
    returned_date DATETIME
);

